const ChemicalSpecies* ChemicalDatabase::find(std::string_view f)const noexcept{const auto it=species_.find(std::string(f));return it==species_.end()?nullptr:&it->second;}
double saturation_vapor_pressure_pa(const ChemicalSpecies&s,double t)noexcept{if(!(t>0)||!std::isfinite(t))return 0;if(t>=s.critical_temperature_k)return s.critical_pressure_pa;const double tref=std::max(s.vapor_reference_temperature_k,1.0),pref=std::max(s.vapor_reference_pressure_pa,1e-12);double latent=s.latent_vaporization_j_mol;if(t<s.triple_temperature_k)latent*=1.20;const double ln=std::log(pref)-latent/kGasConstant*(1.0/t-1.0/tref);return std::clamp(std::exp(std::clamp(ln,-80.0,50.0)),0.0,s.critical_pressure_pa);}
Phase phase_at(const ChemicalSpecies&s,double t,double p)noexcept{if(!(t>0)||!(p>=0)||!std::isfinite(t)||!std::isfinite(p))return Phase::unknown;if(t>=s.critical_temperature_k&&p>=s.critical_pressure_pa)return Phase::supercritical;const double ps=saturation_vapor_pressure_pa(s,t);if(p<ps)return Phase::gas;if(t<s.triple_temperature_k)return Phase::solid;const double melt=s.melting_temperature_k*(1.0+std::clamp((p-s.triple_pressure_pa)/std::max(s.critical_pressure_pa,1.0),-0.02,0.04));if(t<melt)return Phase::solid;return Phase::liquid;}
double liquid_density_kg_m3(const ChemicalSpecies&s,double t)noexcept{const double ref=std::max(s.boiling_temperature_k,1.0);const double expansion=std::clamp(1.0-7.5e-4*(t-ref),0.55,1.25);return std::max(1.0,s.liquid_density_kg_m3*expansion);}
std::vector<CondensateCandidate> atmospheric_condensates(const ChemicalDatabase&db,const AtmosphereComposition&a,double t,double minx){std::vector<CondensateCandidate>out;for(const auto&[f,x0]:a.mole_fraction){if(x0<minx)continue;const auto*s=db.find(f);if(!s||!s->atmospheric_condensable)continue;const double x=std::max(0.0,x0),pp=x*a.surface_pressure_pa,ps=saturation_vapor_pressure_pa(*s,t);if(pp>ps&&t<s->critical_temperature_k){const auto ph=phase_at(*s,t,std::max(pp,ps));out.push_back({f,pp,ps,pp/std::max(ps,1e-30),ph==Phase::gas?(t<s->triple_temperature_k?Phase::solid:Phase::liquid):ph});}}std::sort(out.begin(),out.end(),[](const auto&lhs,const auto&rhs){return lhs.supersaturation>rhs.supersaturation;});return out;}
std::vector<PhotochemicalProduct> photochemistry_products(const AtmosphereComposition&a,double uv){auto x=[&](const char*k){const auto it=a.mole_fraction.find(k);return it==a.mole_fraction.end()?0.0:std::max(0.0,it->second);};uv=std::max(0.0,uv);std::vector<PhotochemicalProduct>o;const double o3=uv*x("O2")*(0.3+0.7*std::tanh(a.surface_pressure_pa/50000.0));if(o3>1e-7)o.push_back({"O3",std::clamp(4.5*o3,0.0,1.0),"O2 photolysis + three-body recombination"});const double haze=uv*x("CH4")*std::sqrt(std::max(x("N2"),1e-9));if(haze>1e-8){o.push_back({"tholins",std::clamp(22.0*haze,0.0,1.0),"UV/particle-driven N2-CH4 organic polymerization"});o.push_back({"hydrocarbon_haze",std::clamp(12.0*haze,0.0,1.0),"CH4 photolysis and hydrocarbon growth"});}const double acid=uv*x("SO2")*std::sqrt(std::max(x("H2O"),0.0));if(acid>1e-10)o.push_back({"H2SO4_aerosol",std::clamp(80.0*acid,0.0,1.0),"SO2 oxidation in the presence of H2O"});const double hcn=uv*x("CH4")*x("N2");if(hcn>1e-9)o.push_back({"HCN",std::clamp(30.0*hcn,0.0,1.0),"N/CH radical photochemistry"});return o;}
GreenhouseResult estimate_greenhouse(const AtmosphereComposition&a,double lum,double dist,double albedo){GreenhouseResult r;lum=std::max(lum,1e-12);dist=std::max(dist,1e-6);albedo=std::clamp(albedo,0.0,0.95);r.equilibrium_temperature_k=278.5*std::pow(lum/(dist*dist),0.25)*std::pow((1-albedo)/0.7,0.25);const std::map<std::string,std::pair<double,double>>coeff{{"H2O",{1.30,1200}},{"CO2",{0.55,40}},{"CH4",{0.42,1.8}},{"NH3",{0.75,0.7}},{"SO2",{0.18,1.0}},{"H2",{0.10,10000}},{"CO",{0.03,1000}}};for(const auto&[f,xv]:a.mole_fraction){const auto it=coeff.find(f);if(it==coeff.end())continue;const double pbar=std::max(0.0,xv*a.surface_pressure_pa/1e5);const auto[c,ppmref]=it->second;const double pref=ppmref*1e-6;const double tau=c*std::log1p(pbar/std::max(pref,1e-12));r.optical_depth_by_species[f]=tau;r.optical_depth+=tau;}const double broad=std::pow(std::max(a.surface_pressure_pa/101325.0,0.01),0.18);r.optical_depth*=broad;r.surface_temperature_k=r.equilibrium_temperature_k*std::pow(1.0+0.75*std::max(r.optical_depth,0.0),0.25);r.greenhouse_delta_k=r.surface_temperature_k-r.equilibrium_temperature_k;return r;}
